import json
from pathlib import Path

import pyarrow.parquet as pq


def describe(value):
    if isinstance(value, str):
        parsed = None
        try:
            parsed = json.loads(value)
        except (json.JSONDecodeError, TypeError):
            pass
        return {
            "type": "str",
            "chars": len(value),
            "json_type": type(parsed).__name__ if parsed is not None else None,
            "snippet": value[:120].replace("\n", "\\n"),
        }
    if isinstance(value, list):
        return {
            "type": "list",
            "length": len(value),
            "item_types": sorted({type(item).__name__ for item in value}),
            "first": describe(value[0]) if value else None,
        }
    if isinstance(value, dict):
        return {"type": "dict", "keys": sorted(value), "sample": {k: describe(value[k]) for k in list(value)[:4]}}
    return {"type": type(value).__name__, "value": value}


root = Path("local_soul_eval/data")
for path in sorted(root.glob("*_val.parquet")):
    table = pq.read_table(path)
    row = table.slice(0, 1).to_pylist()[0]
    payload = row.get("extra_info") if isinstance(row.get("extra_info"), dict) else row
    if isinstance(payload, dict) and isinstance(payload.get("raw"), str):
        payload = {**payload, **json.loads(payload["raw"])}
    interesting = {
        key: describe(payload.get(key))
        for key in (
            "human_user_queries",
            "human_public_conversation",
            "completion",
            "prompt",
            "persona",
            "dataset",
            "category",
        )
        if isinstance(payload, dict) and key in payload
    }
    print(json.dumps({
        "file": path.name,
        "rows": table.num_rows,
        "schema": str(table.schema),
        "row_keys": sorted(row),
        "payload_keys": sorted(payload) if isinstance(payload, dict) else None,
        "interesting": interesting,
    }))

results = Path("local_soul_eval/outputs/openai_gpt-5.6-luna_41496463/results.jsonl")
seen = set()
for line in results.open():
    record = json.loads(line)
    if record["task"] in seen:
        continue
    seen.add(record["task"])
    messages = record.get("messages", [])
    print(json.dumps({
        "result_task": record["task"],
        "record_keys": sorted(record),
        "metric_keys": sorted(record.get("metrics", {})),
        "message_roles": [message.get("role") for message in messages],
        "message_chars": [len(str(message.get("content", ""))) for message in messages],
        "message_keys": [sorted(message) for message in messages],
    }))

