{"i":0,"output":""""Small compatibility layer for running OdysSim agents without VERL.

The copied agents only need message generation, structured judge calls, a chat
container, and a compact output object.  Keeping those pieces here avoids
installing the full training stack or downloading a tokenizer checkpoint.
"""

from __future__ import annotations

import asyncio
import json
import logging
import os
import re
from typing import Any

from openai import AsyncOpenAI
from pydantic import BaseModel

LOGGER = logging.getLogger(__name__)
_CLIENT: AsyncOpenAI | None = None


def _client() -> AsyncOpenAI:
    global _CLIENT
    if _CLIENT is None:
        api_key = os.environ.get("OPENAI_API_KEY") or os.environ.get("OPENAI_AGENT_API_KEY")
        base_url = os.environ.get("OPENAI_BASE_URL") or os.environ.get("OPENAI_AGENT_BASE_URL")
        if not api_key:
            raise RuntimeError("OPENAI_API_KEY is not set")
        _CLIENT = AsyncOpenAI(api_key=api_key, base_url=base_url or None, timeout=180.0)
    return _CLIENT


def _model(requested: str) -> str:
    return os.environ.get("OPENAI_EVAL_MODEL") or requested


def get_judge_model(default: str) -> str:
    return os.environ.get("OPENAI_EVAL_MODEL") or os.environ.get("JUDGE_MODEL_NAME") or default


def get_judge_reasoning(default: str) -> str:
    return os.environ.get("JUDGE_MODEL_REASONING") or default


def remove_think(text: str | None) -> str:
    if not text:
        return ""
    return re.sub(r"^\s*<(?:seed:)?think>.*?</(?:seed:)?think>\s*", "", text, flags=re.DOTALL)


def _reasoning_value(value: Any) -> str | None:
    if isinstance(value, dict):
        value = value.get("effort")
    if value in {"minimal", "low", "medium", "high", "xhigh"}:
        return value
    return None


async def _chat_text(
    messages: list[dict[str, Any]],
    model: str,
    *,
    reasoning_effort: Any = None,
    response_format: dict[str, Any] | None = None,
    max_completion_tokens: int | None = None,
) -> str:
    kwargs: dict[str, Any] = {"model": _model(model), "messages": messages}
    effort = _reasoning_value(reasoning_effort)
    if effort:
        kwargs["reasoning_effort"] = effort
    if response_format is not None:
        kwargs["response_format"] = response_format
    if max_completion_tokens is not None:
        kwargs["max_completion_tokens"] = max_completion_tokens

    try:
        response = await _client().chat.completions.create(**kwargs)
    except Exception as exc:
        # A few OpenAI-compatible gateways reject reasoning_effort even when
        # the underlying model supports reasoning. Retry once without it.
        error_text = str(exc).lower()
        if "reasoning_effort" not in kwargs or not any(
            marker in error_text
            for marker in ("reasoning_effort", "reasoning effort", "unsupported parameter", "unknown parameter")
        ):
            raise
        LOGGER.warning("Retrying without reasoning_effort after API rejection: %s", exc)
        kwargs.pop("reasoning_effort", None)
        response = await _client().chat.completions.create(**kwargs)

    content = response.choices[0].message.content
    if isinstance(content, str):
        return content
    if content is None:
        return ""
    return str(content)


async def call_openai(
    messages: list[dict[str, Any]] | str,
    model: str = "gpt-5-nano",
    max_retries: int = 3,
    response_format: dict[str, Any] | None = None,
    reasoning_effort: Any = "low",
) -> str:
    if isinstance(messages, str):
        messages = [{"role": "user", "content": messages}]
    last_error: Exception | None = None
    for attempt in range(max_retries):
        try:
            text = await _chat_text(
                messages,
                model,
                reasoning_effort=reasoning_effort,
                response_format=response_format,
            )
            if text:
                return text
            raise RuntimeError("API returned an empty completion")
        except Exception as exc:
            last_error = exc
            if attempt + 1 < max_retries:
                await asyncio.sleep(min(8, 2**attempt))
    raise RuntimeError(f"completion failed after {max_retries} attempts: {last_error}")


def _json_from_text(text: str) -> Any:
    candidate = text.strip()
    if candidate.startswith("```"):
        candidate = re.sub(r"^```(?:json)?\s*", "", candidate, flags=re.IGNORECASE)
        candidate = re.sub(r"\s*```$", "", candidate)
    try:
        return json.loads(candidate)
    except json.JSONDecodeError:
        start = candidate.find("{")
        end = candidate.rfind("}")
        if start >= 0 and end > start:
            return json.loads(candidate[start : end + 1])
        raise


def _strict_json_schema(value: Any) -> Any:
    """Make Pydantic's schema acceptable to OpenAI strict structured output."""
    if isinstance(value, dict):
        result = {key: _strict_json_schema(item) for key, item in value.items()}
        if result.get("type") == "object" or "properties" in result:
            result["additionalProperties"] = False
            if "properties" in result:
                result["required"] = list(result["properties"])
        return result
    if isinstance(value, list):
        return [_strict_json_schema(item) for item in value]
    return value


async def call_openai_parse(
    messages: list[dict[str, Any]] | str,
    text_format: type[BaseModel],
    model: str = "gpt-5-nano",
    max_retries: int = 3,
    reasoning_effort: Any = "low",
    **kwargs: Any,
) -> dict[str, Any]:
    if isinstance(messages, str):
        messages = [{"role": "user", "content": messages}]
    effort = kwargs.get("reasoning", reasoning_effort)
    schema = _strict_json_schema(text_format.model_json_schema())
    schema_name = re.sub(r"[^A-Za-z0-9_-]", "_", text_format.__name__)[:64]
    schema_instruction = (
        "\n\nReturn only one JSON object matching this JSON Schema exactly:\n"
        + json.dumps(schema, separators=(",", ":"))
    )
    prompted = [dict(message) for message in messages]
    prompted[-1] = {
        **prompted[-1],
        "content": str(prompted[-1].get("content", "")) + schema_instruction,
    }

    formats: list[dict[str, Any] | None] = [
        {"type": "json_schema", "json_schema": {"name": schema_name, "strict": True, "schema": schema}},
        {"type": "json_object"},
        None,
    ]
    last_error: Exception | None = None
    attempts = max(max_retries, len(formats))
    for attempt in range(attempts):
        response_format = formats[min(attempt, len(formats) - 1)]
        try:
            text = await _chat_text(
                prompted,
                model,
                reasoning_effort=effort,
                response_format=response_format,
            )
            parsed = text_format.model_validate(_json_from_text(text))
            return parsed.model_dump(by_alias=True)
        except Exception as exc:
            last_error = exc
            if attempt + 1 < attempts:
                await asyncio.sleep(min(8, 2**attempt))
    raise RuntimeError(f"structured completion failed after {attempts} attempts: {last_error}")


class OpenAIModelClient:
    """Message-based substitute for VERL's rollout client."""

    def __init__(self, model: str, max_completion_tokens: int = 8192):
        self.model = model
        self.max_completion_tokens = max_completion_tokens

    async def create_completion(self, input_ids=None, **kwargs: Any) -> dict[str, Any]:
        messages = kwargs.get("messages")
        if messages is None:
            raise ValueError("messages are required by the lightweight client")
        text = await _chat_text(
            messages,
            self.model,
            reasoning_effort=os.environ.get("OPENAI_AGENT_REASONING_EFFORT", "low"),
            max_completion_tokens=self.max_completion_tokens,
        )
        return {"choices": [{"message": {"role": "assistant", "content": text}}]}


"}

