import asyncio
import os
import sys
import unittest
from pathlib import Path
from types import SimpleNamespace

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from agents import utils
import humanual_reuse


class _FakeCompletions:
    def __init__(self):
        self.kwargs = None

    async def create(self, **kwargs):
        self.kwargs = kwargs
        return SimpleNamespace(
            choices=[SimpleNamespace(message=SimpleNamespace(content="ok"))]
        )


class FixedRoleRoutingTests(unittest.TestCase):
    def setUp(self):
        self.names = (
            "OPENAI_EVAL_MODEL",
            "OPENAI_ASSISTANT_MODEL",
            "OPENAI_DOCUMENT_GENERATOR_MODEL",
            "OPENAI_JUDGE_MODEL",
            "JUDGE_MODEL_NAME",
        )
        self.saved = {name: os.environ.get(name) for name in self.names}
        for name in self.names:
            os.environ.pop(name, None)

    def tearDown(self):
        for name, value in self.saved.items():
            if value is None:
                os.environ.pop(name, None)
            else:
                os.environ[name] = value
        utils._CLIENT = None

    def test_roles_can_be_configured_independently(self):
        os.environ["OPENAI_ASSISTANT_MODEL"] = "assistant-model"
        os.environ["OPENAI_DOCUMENT_GENERATOR_MODEL"] = "document-model"
        os.environ["OPENAI_JUDGE_MODEL"] = "judge-model"
        self.assertEqual(utils.get_assistant_model("default"), "assistant-model")
        self.assertEqual(utils.get_document_generator_model("default"), "document-model")
        self.assertEqual(utils.get_judge_model("default"), "judge-model")

    def test_legacy_eval_override_cannot_replace_requested_role_model(self):
        completions = _FakeCompletions()
        utils._CLIENT = SimpleNamespace(
            chat=SimpleNamespace(completions=completions)
        )
        os.environ["OPENAI_EVAL_MODEL"] = "wrong-target-override"
        text = asyncio.run(
            utils._chat_text(
                [{"role": "user", "content": "hello"}],
                "fixed-role-model",
            )
        )
        self.assertEqual(text, "ok")
        self.assertEqual(completions.kwargs["model"], "fixed-role-model")

    def test_reused_humanual_answer_is_extracted_without_regeneration(self):
        source = {
            "messages": [
                {"role": "system", "content": "persona"},
                {"role": "assistant", "content": "<think>hidden</think><response>saved answer</response>"},
            ]
        }
        self.assertEqual(humanual_reuse.generated_response(source), "saved answer")
        self.assertEqual(
            humanual_reuse.prompt_text(
                {"prompt": '[{"role":"user","content":"first"},{"role":"user","content":"second"}]'}
            ),
            "first\nsecond",
        )


if __name__ == "__main__":
    unittest.main()

